    .hero { min-height: 194px; padding: 23px; }
    .hero canvas { right: -224px; opacity: .48; }
    .hero p { font-size: .88rem; }
    section { margin-top: 26px; }
    .comparison { grid-template-columns: 1fr; gap: 12px; }
    .chart { padding: 17px; }
