    tbody tr { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); padding: 12px 14px; border-top: 1px solid var(--line); gap: 7px 12px; }
    tbody tr:first-child { border-top: 0; }
    tbody th, tbody td { border: 0; padding: 0; overflow-wrap: anywhere; }
    tbody .number { text-align: left; }
    tbody td:nth-child(2) { text-align: right; }
    .mobile-label { display: block; color: var(--muted); font-size: .75rem; }
    .action { grid-column: 1 / -1; }
  }
  @media (max-width: 340px) {
    .brand { font-size: 1rem; gap: 7px; }
    .button { padding-inline: 11px; }
    .form-fields { grid-template-columns: 1fr; }
  }
</style>
</head>
<body>
<header class="top">
  <div class="shell">
    <div class="brand"><span class="mark"><canvas id="brand-mark" width="52" height="52" style="width:26px;height:26px" aria-hidden="true"></canvas></span>Flower Stall</div>
    <div class="top-actions">
      <span class="local">Offline ledger</span>
      <button class="button primary" id="add" type="button"><span class="plus" aria-hidden="true">+</span> Add entry</button>
    </div>
  </div>
</header>
<main class="shell">
  <div class="hero">
    <canvas id="botanical" width="930" height="464" aria-hidden="true"></canvas>
    <div class="hero-copy">
      <div id="date-range" class="hero-date"></div>
      <h1>Weekend sales review</h1>
      <p>See how weather relates to bouquet sales at the stall.</p>
