        <div class="chart-rows" id="sell-chart"></div>
      </article>
      <article class="chart" aria-labelledby="revenue-title">
        <div class="chart-head"><h3 id="revenue-title">Revenue per open hour</h3><p>Revenue ÷ hours open</p></div>
        <div class="chart-rows" id="revenue-chart"></div>
      </article>
    </div>
  </section>
  <section aria-labelledby="log-heading">
    <div class="section-head">
      <h2 id="log-heading">Sales log</h2>
      <p id="entry-count"></p>
    </div>
    <div class="ledger">
      <table role="table" aria-labelledby="log-heading">
        <thead role="rowgroup"><tr role="row">
          <th scope="col" role="columnheader">Date</th><th scope="col" role="columnheader">Weather</th>
          <th scope="col" role="columnheader" class="number">Hours open</th>
          <th scope="col" role="columnheader" class="number">Bouquets brought</th>
          <th scope="col" role="columnheader" class="number">Bouquets sold</th>
          <th scope="col" role="columnheader" class="number">Revenue</th>
          <th scope="col" role="columnheader"><span class="sr-only">Actions</span></th>
        </tr></thead>
        <tbody role="rowgroup" id="entries"></tbody>
      </table>
    </div>
  </section>
  <footer>Entries are saved in this browser. Reopen this file in the same browser to keep working.</footer>
</main>
<dialog id="editor" aria-labelledby="editor-title">
  <form id="entry-form">
    <h2 id="editor-title">Add entry</h2>
    <div class="form-fields">
      <label>Date<input name="date" type="date" required autofocus></label>
      <label>Weather<select name="weather" required><option value="">Choose weather</option><option value="dry">Dry</option><option value="rain">Rain</option></select></label>
      <label>Hours open<input name="hours" type="number" min="0" step="any" required inputmode="decimal"></label>
      <label>Revenue (whole dollars)<input name="revenue" type="number" min="0" max="9007199254740991" step="1" required inputmode="numeric"></label>
      <label>Bouquets brought<input name="brought" type="number" min="0" max="9007199254740991" step="1" required inputmode="numeric"></label>
      <label>Bouquets sold<input name="sold" type="number" min="0" max="9007199254740991" step="1" required inputmode="numeric" aria-describedby="form-error"></label>
    </div>
    <p id="form-error" class="form-error error" role="alert"></p>
    <div class="form-actions">
      <button class="button secondary" id="cancel" type="button">Cancel</button>
      <button class="button primary" type="submit">Save entry</button>
    </div>
  </form>
</dialog>
<template id="weather-template"><span class="weather"><canvas width="28" height="28" aria-hidden="true"></canvas><span></span></span></template>
<script>
  '"'use strict';

  const seed = [
    ['2026-05-02', 'dry', 4, 36, 31, 310],
    ['2026-05-03', 'rain', 3, 30, 14, 140],
    ['2026-05-09', 'dry', 5, 45, 42, 420],
    ['2026-05-10', 'rain', 4, 32, 19, 190],
    ['2026-05-16', 'dry', 4, 40, 35, 350],
    ['2026-05-17', 'rain', 2, 25, 9, 90],
  ].map(([date, weather, hours, brought, sold, revenue], id) => ({ id: 'seed-' + id, date, weather, hours, brought, sold, revenue }));

  const storageKey = 'flower-stall-ledger-v1';
  const labels = { dry: 'Dry', rain: 'Rain' };
  const weatherTypes = Object.keys(labels);
  const count = new Intl.NumberFormat('en-US');
  const hoursFormat = new Intl.NumberFormat('en-US', { maximumSignificantDigits: 15 });
  const dollars = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  const hourly = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
  const percent = new Intl.NumberFormat('en-US', { style: 'percent', maximumFractionDigits: 1, minimumFractionDigits: 1 });
  const fullDate = new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' });
  const monthDay = new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' });
  const dayOnly = new Intl.DateTimeFormat('en-US', { day: 'numeric', timeZone: 'UTC' });
  const byId = id => document.getElementById(id);
  const editor = byId('editor');
  const form = byId('entry-form');
  const fields = form.elements;
  const formError = byId('form-error');
  let entries = seed;
  let editing = null;
  let returnFocus = null;

  function report(message, error = false) {
    const status = byId('status');
    status.textContent = message;
    status.classList.toggle('error', error);
  }

  function readEntries() {
    const raw = localStorage.getItem(storageKey);
    if (raw === null) return seed;
    const list = JSON.parse(raw);
    if ("'!Array.isArray(list) || list.some(entry => !entry || typeof entry.id !== '"'string' || validationError(entry)) ||
        new Set(list.map(entry => entry.id)).size "'!== list.length) {
      throw new Error('"'Invalid ledger');
    }
    return list;
  }

  function validationError(entry) {
    const date = new Date(entry.date + 'T00:00:00Z');
    if ("'!/''^'"\\d{4}-\\d{2}-\\d{2}"'$/.test(entry.date) || !Number.isFinite(+date) ||
        date.toISOString().slice(0, 10) !== entry.date || entry.date.startsWith('"'0000')) {
      return 'Enter a valid date between years 1 and 9999.';
    }
    if ("'!weatherTypes.includes(entry.weather)) return '"'Choose dry or rain.';
    if ("'!Number.isFinite(entry.hours) || entry.hours < 0) return '"'Enter zero or more hours open.';
    if ("'!['"'brought', 'sold', 'revenue'].every(key => Number.isSafeInteger(entry[key]) && entry[key] >= 0)) {
      return 'Use nonnegative whole numbers for bouquet counts and revenue.';
    }
    if (entry.sold > entry.brought) return 'Bouquets sold cannot exceed bouquets brought.';
    return '';
  }

  function summarize(list) {
    const totals = Object.fromEntries(weatherTypes.map(weather => [weather, { sessions: 0, hours: 0, brought: 0, sold: 0, revenue: 0 }]));
    for (const entry of list) {
      const total = totals[entry.weather];
      total.sessions++;
      for (const key of ['hours', 'brought', 'sold', 'revenue']) total[key] += entry[key];
    }
    for (const total of Object.values(totals)) {
      total.sellThrough = total.brought ? total.sold / total.brought : null;
      total.perHour = total.hours ? total.revenue / total.hours : null;
    }
    return totals;
  }

  function dateRange(sorted) {
    if ("'!sorted.length) return '"'No recorded dates';
    const first = new Date(sorted.at(-1).date + 'T00:00:00Z');
    const last = new Date(sorted[0].date + 'T00:00:00Z');
    if (+first === +last) return fullDate.format(last);
    if (first.getUTCFullYear() "'!== last.getUTCFullYear()) return fullDate.format(first) + '"' – ' + fullDate.format(last);
    if (first.getUTCMonth() === last.getUTCMonth()) return monthDay.format(first) + '–' + dayOnly.format(last) + ', ' + last.getUTCFullYear();
    return monthDay.format(first) + ' – ' + fullDate.format(last);
  }

  function element(tag, className, value) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (value "'!== undefined) node.textContent = value;
    return node;
  }

  function weatherBadge(weather) {
    const badge = byId('"'weather-template').content.firstElementChild.cloneNode(true);
    badge.classList.add(weather);
    badge.querySelector('span').textContent = labels[weather];
    const ctx = badge.querySelector('canvas').getContext('2d');
    ctx.scale(2, 2);
    ctx.lineWidth = 1.1;
    ctx.lineCap = 'round';
    ctx.strokeStyle = weather === 'dry' ? '#835417' : '#38616b';
    ctx.beginPath();
    if (weather === 'dry') {
      ctx.arc(7, 7, 2.6, 0, Math.PI * 2);
      for (let ray = 0; ray < 8; ray++) {
        const angle = ray * Math.PI / 4;
        ctx.moveTo(7 + Math.cos(angle) * 4.3, 7 + Math.sin(angle) * 4.3);
        ctx.lineTo(7 + Math.cos(angle) * 5.6, 7 + Math.sin(angle) * 5.6);
      }
    } else {
      ctx.moveTo(3, 8.5);
      ctx.bezierCurveTo(0, 8.5, 1.2, 3.9, 4.2, 4.6);
      ctx.bezierCurveTo(5, 1.1, 9.7, 1.5, 10.3, 4.9);
      ctx.bezierCurveTo(13.9, 4.3, 14, 8.5, 11.6, 8.5);
      ctx.lineTo(3, 8.5);
      for (const x of [5, 9]) {
        ctx.moveTo(x, 10.3);
        ctx.lineTo(x - 1, 12.2);
      }
    }
    ctx.stroke();
    return badge;
  }

  function renderChart(target, totals, metric, format, basis, scale) {
    target.replaceChildren(...weatherTypes.map(weather => {
      const total = totals[weather];
      const value = total[metric];
      const row = element('div', 'chart-row');
      const values = element('div', 'chart-values');
      const rate = element('strong', 'metric', value === null ? '—' : format.format(value));
      if (value === null) rate.setAttribute('aria-label', 'Rate unavailable');
      values.append(weatherBadge(weather), rate);
      const track = element('div', 'track');
      track.setAttribute('aria-hidden', 'true');
      const bar = element('div', 'bar ' + weather);
      bar.style.width = (value === null ? 0 : value / scale * 100) + '%';
      track.append(bar);
      const sessions = count.format(total.sessions) + (total.sessions === 1 ? ' session' : ' sessions');
      row.append(values, track, element('p', 'basis', basis(total) + ' · ' + sessions));
      return row;
    }));
  }

  function numberCell(label, value) {
    const cell = element('td', 'number');
    cell.setAttribute('role', 'cell');
    const mobileLabel = element('span', 'mobile-label', label);
    mobileLabel.setAttribute('aria-hidden', 'true');
    cell.append(mobileLabel, document.createTextNode(value));
    return cell;
  }

  function render() {
    const totals = summarize(entries);
    renderChart(byId('sell-chart'), totals, 'sellThrough', percent,
      t => count.format(t.sold) + ' sold / ' + count.format(t.brought) + ' brought', 1);
    const maxHourly = Math.max(1, ...weatherTypes.map(weather => totals[weather].perHour ?? 0));
    renderChart(byId('revenue-chart'), totals, 'perHour', hourly,
      t => dollars.format(t.revenue) + ' revenue / ' + hoursFormat.format(t.hours) + ' ' + (t.hours === 1 ? 'hour' : 'hours'), maxHourly);
    const sorted = [...entries].sort((a, b) => b.date.localeCompare(a.date));
    byId('date-range').textContent = dateRange(sorted);
    byId('entry-count').textContent = count.format(entries.length) + (entries.length === 1 ? ' recorded session' : ' recorded sessions');
    byId('entries').replaceChildren(...sorted.map(entry => {
      const row = element('tr');
      row.setAttribute('role', 'row');
      const dateLabel = fullDate.format(new Date(entry.date + 'T00:00:00Z'));
      const date = element('th', '', dateLabel);
      date.scope = 'row';
      date.setAttribute('role', 'rowheader');
      const weather = element('td');
      weather.setAttribute('role', 'cell');
      weather.append(weatherBadge(entry.weather));
      const action = element('td', 'action');
      action.setAttribute('role', 'cell');
      const edit = element('button', 'edit', 'Edit');
      edit.type = 'button';
      edit.dataset.id = entry.id;
      edit.setAttribute('aria-label', 'Edit entry for ' + dateLabel + ', ' + labels[entry.weather]);
      edit.addEventListener('click', () => openEditor(entry, edit));
      action.append(edit);
      row.append(date, weather, numberCell('Hours open', hoursFormat.format(entry.hours)),
        numberCell('Bouquets brought', count.format(entry.brought)), numberCell('Bouquets sold', count.format(entry.sold)),
        numberCell('Revenue', dollars.format(entry.revenue)), action);
      return row;
    }));
  }

  function openEditor(entry, trigger) {
    editing = entry;
    returnFocus = trigger;
    form.reset();
    formError.textContent = '';
    byId('editor-title').textContent = entry ? 'Edit entry' : 'Add entry';
    if (entry) {
      for (const key of ['date', 'weather', 'hours', 'brought', 'sold', 'revenue']) fields[key].value = entry[key];
    }
    editor.showModal();
  }

  byId('add').addEventListener('click', event => openEditor(null, event.currentTarget));
  byId('cancel').addEventListener('click', () => editor.close());
  editor.addEventListener('close', () => (returnFocus?.isConnected ? returnFocus : byId('add')).focus());
  form.addEventListener('input', () => { formError.textContent = ''; });

  form.addEventListener('submit', event => {
    event.preventDefault();
    const entry = {
      id: editing?.id ?? crypto.randomUUID(),
      date: fields.date.value,
      weather: fields.weather.value,
      hours: fields.hours.valueAsNumber,
      brought: fields.brought.valueAsNumber,
      sold: fields.sold.valueAsNumber,
      revenue: fields.revenue.valueAsNumber,
    };
    const error = validationError(entry);
    if (error) {
      formError.textContent = error;
      if (entry.sold > entry.brought) fields.sold.focus();
      return;
    }
    try {
      const latest = readEntries();
      if (editing && JSON.stringify(latest.find(item => item.id === editing.id)) "'!== JSON.stringify(editing)) {
        formError.textContent = '"'This entry changed in another tab. Cancel and open the updated entry before correcting it.';
